/** REG-ARCH-ACC2: indexado temporal (S151/FILE/ACC2) con llave ACC-CUENTA 9(11). */
@Entity
@Table(name = "S151_P168_SALDO_ACC")
public class SaldoAcc {
    @Id @Column(length = 11) private String cuenta;            // ACC-CUENTA 9(11): String, conserva ceros
    @Column(length = 11)     private String ctaFtoBanamex;     // ACC-CTA-FTOBANAMEX (no se llena en P168)
    @Column(precision = 16, scale = 2) private BigDecimal saldo;   // ACC-SALDO 9(14)V99
    @Column(length = 1)      private String signo;             // ACC-SSDO: "+" o "-"
}

/** REG-ARCH-CTAS: cuenta descuadrada. Nótese que el saldo AHR se guarda con dos enteros menos. */
public record DiferenciaSaldo(String cuenta,          // WKS-CTA-AHR  9(11)
                              BigDecimal saldoAhr,    // WKS-SDO-AHR  9(12)V99
                              BigDecimal saldoAcc,    // WKS-SDO-ACC  9(14)V99
                              char signoAhr,          // WKS-SSDO-AHR
                              char signoAcc) {        // WKS-SSDO-ACC (espacio si la cuenta no existe en ACC)
    public static final BigDecimal TOPE_AHR = new BigDecimal("999999999999.99");
    public DiferenciaSaldo {
        if (saldoAhr.compareTo(TOPE_AHR) > 0)
            throw new DesbordamientoCampoException("WKS-SDO-AHR", saldoAhr);   // COBOL truncaría
    }
}

@Component
@RequiredArgsConstructor
public class CargaAccTasklet implements Tasklet {

    private static final String FIN_ARCHIVO = "END OF FILE";   // ACCI-ENDOFFILE del trailer
    private final SaldoAccRepository saldos;
    private final FlatFileItemReader<RegistroAcc> accReader;   // ARCH-ACC, 360 bytes, layout CBII

    @Override
    @Transactional
    public RepeatStatus execute(StepContribution sc, ChunkContext ctx) throws Exception {
        saldos.deleteAllInBatch();                             // OPEN OUTPUT / CLOSE / OPEN I-O: recrea vacío
        accReader.open(new ExecutionContext());
        try {
            for (RegistroAcc r; (r = accReader.read()) != null; ) {
                if (r.raw().startsWith(FIN_ARCHIVO)) break;   // trailer de CBII
                var s = new SaldoAcc(r.numeroCuenta(),
                        Pic.trunca(r.saldo(), 14, 2),          // 9(15)V99 a 9(14)V99
                        r.signoSaldo());
                if (!saldos.existsById(s.getCuenta())) {
                    saldos.save(s);                            // WRITE ... INVALID KEY NEXT SENTENCE
                } else {
                    sc.incrementFilterCount(1);                // duplicado: gana el primero, sin aviso en el fuente
                }
            }
        } finally {
            accReader.close();
        }
        return RepeatStatus.FINISHED;
    }
}

