p168:
  transferencia:
    programa-default: "(S006)S006/OBJECT/P940/CTRLFTP/25MTP001 ON XFER"   # si CTLVERS falla
    prefijo-sistema: "S500"          # WKS-START-SIS VALUE 500, aunque el paso es de S151
    sufijo-archivo: "INTE"
    consecutivo: 1

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
public class TransferenciaIntelTasklet implements Tasklet {

    private final CatalogoVersiones ctlvers;      // DAME_TIT IN CTRLVERS
    private final TransferenciaPort ctrlftp;      // S006P940 CTRLFTP
    private final P168Properties props;

    @Override
    public RepeatStatus execute(StepContribution sc, ChunkContext ctx) {
        var t = props.transferencia();
        String programa = ctlvers.titulo("S006P940").orElse(t.programaDefault());
        LocalDate fecha = (LocalDate) ctx.getStepContext().getJobExecutionContext().get("fechaProceso");
        String parametro = "%s%s/%s/%02d".formatted(t.prefijoSistema(), t.sufijoArchivo(),
                fecha.format(DateTimeFormatter.BASIC_ISO_DATE), t.consecutivo());
        ctrlftp.ejecuta(programa, parametro);     // antes: CALL SYSTEM WFL "BEGIN JOB; RUN ... ; END JOB."
        return RepeatStatus.FINISHED;
    }
}
